package com.vit.archds.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="decisions") public class Decision { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="project_id") private Project project; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="candidate_id") private ArchitectureCandidate candidate; @Column(length=4000) private String rationale; @Column(nullable=false) private Instant createdAt=Instant.now(); public Decision(){} public Decision(Project p,ArchitectureCandidate c,String r){project=p;candidate=c;rationale=r;} }
